package br.com.marquesautodetail.api.security;
import br.com.marquesautodetail.api.usuario.Usuario;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.*;
@Service public class JwtService{ @Value("${app.jwt.secret}") private String secret; @Value("${app.jwt.expiration-ms}") private long expirationMs; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String gerarToken(Usuario u){Date now=new Date();return Jwts.builder().subject(u.getEmail()).claim("role",u.getRole().name()).claim("id",u.getId()).issuedAt(now).expiration(new Date(now.getTime()+expirationMs)).signWith(key()).compact();} public String getEmail(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload().getSubject();} }
